1	import {
2	  SHOP_KEYS,
3	  type CatalogResponse,
4	  type DataSource,
5	  type Product,
6	  type ShopKey,
7	  type ShopStatus,
8	  type ShopSummary,
9	} from "@organic/shared";
10	import type { ShopAdapter, ShopFetchResult } from "../shops/types";
11	import type { TtlCache } from "./cache";
12	import type { SnapshotSource } from "./snapshot";
13	
14	/** One entry per configured shop: that shop's full upstream list, before the visibility rule. */
15	export type ShopProducts = { key: ShopKey; products: Product[] };
16	
17	const VISIBLE_PER_SHOP = 10;
18	
19	/**
20	 * The only place that decides which products the storefront shows: the first ten of each shop in upstream
21	 * order, shops concatenated in configured order. Pure, so `add-admin` replaces this function alone.
22	 */
23	export function selectVisibleProducts(perShop: ShopProducts[]): Product[] {
24	  return [...perShop]
25	    .sort((a, b) => SHOP_KEYS.indexOf(a.key) - SHOP_KEYS.indexOf(b.key))
26	    .flatMap((shop) => shop.products.slice(0, VISIBLE_PER_SHOP));
27	}
28	
29	export interface CatalogShop {
30	  adapter: ShopAdapter;
31	  snapshotKey: ShopKey;
32	}
33	
34	export interface CatalogServiceOptions {
35	  source: DataSource;
36	  shops: CatalogShop[];
37	  snapshots: SnapshotSource;
38	  cache: TtlCache<Product[]>;
39	  now: () => number;
40	}
41	
42	export interface CatalogService {
43	  getSource(): DataSource;
44	  setSource(source: DataSource): void;
45	  load(): Promise<CatalogResponse>;
46	  findProduct(id: string): Promise<Product | undefined>;
47	}
48	
49	interface ResolvedShop {
50	  key: ShopKey;
51	  products: Product[];
52	  status: ShopStatus;
53	  error?: string;
54	}
55	
56	export function createCatalogService(options: CatalogServiceOptions): CatalogService {
57	  const { shops, snapshots, cache } = options;
58	  let source = options.source;
59	  // One adapter call per shop while it is in flight, so concurrent cold loads share it.
60	  const inFlight = new Map<ShopKey, Promise<ShopFetchResult>>();
61	
62	  function fetchOnce(shop: CatalogShop): Promise<ShopFetchResult> {
63	    const key = shop.adapter.shop.key;
64	    const started = inFlight.get(key);
65	    if (started) return started;
66	    const call = shop.adapter.fetchProducts().finally(() => inFlight.delete(key));
67	    inFlight.set(key, call);
68	    return call;
69	  }
70	
71	  /** The snapshot is the last resort: when it cannot be read the shop is reported, not thrown. */
72	  async function fromSnapshot(
73	    shop: CatalogShop,
74	    status: ShopStatus,
75	    error?: string,
76	  ): Promise<ResolvedShop> {
77	    const key = shop.adapter.shop.key;
78	    const failure = error === undefined ? {} : { error };
79	    try {
80	      return { key, products: await snapshots.read(shop.snapshotKey), status, ...failure };
81	    } catch {
82	      return { key, products: [], status: "unavailable", ...failure };
83	    }
84	  }
85	
86	  async function resolveShop(shop: CatalogShop): Promise<ResolvedShop> {
87	    const key = shop.adapter.shop.key;
88	    if (source === "snapshot") return fromSnapshot(shop, "snapshot");
89	
90	    const cached = cache.get(key);
91	    if (cached) return { key, products: cached, status: "live" };
92	
93	    const result = await fetchOnce(shop);
94	    if (result.ok) {
95	      // Only successes are cached, so the next request retries a shop that was down.
96	      cache.set(key, result.products);
97	      return { key, products: result.products, status: "live" };
98	    }
99	    return fromSnapshot(shop, "snapshot-fallback", result.error);
100	  }
101	
102	  async function load(): Promise<CatalogResponse> {
103	    const resolved = await Promise.all(
104	      shops.map(async (shop) => ({ shop, state: await resolveShop(shop) })),
105	    );
106	    const products = selectVisibleProducts(resolved.map(({ state }) => ({ key: state.key, products: state.products })));
107	    const summaries: ShopSummary[] = resolved.map(({ shop, state }) => ({
108	      key: state.key,
109	      name: shop.adapter.shop.name,
110	      url: shop.adapter.shop.url,
111	      status: state.status,
112	      ...(state.error === undefined ? {} : { error: state.error }),
113	      count: products.filter((product) => product.shopKey === state.key).length,
114	    }));
115	    return { source, shops: summaries, products };
116	  }
117	
118	  return {
119	    getSource: () => source,
120	    setSource(next) {
121	      source = next;
122	    },
123	    load,
124	    // Goes through the same mode / cache / fallback path, so it answers on a cold service too.
125	    async findProduct(id) {
126	      return (await load()).products.find((product) => product.id === id);
127	    },
128	  };
129	}
