4	const SHOP_KEY = "karashynyard";
5	const PAGE_URL = "https://karashynyard.com.ua/";
6	
7	// The page is one Tilda document: records open with `<div id="recNNN" … data-record-type="NN">`, product cards
8	// live in type-776 records, and the category of a card is the title of the nearest preceding heading record.
9	const RECORD_RE = /<div id="(rec\d+)"[^>]*\sdata-record-type="(\d+)"[^>]*>/g;
10	// Only `t776__col … js-product` is a card. Every record also carries one `t776__product-full js-product` popup
11	// block per card with the same lid, so matching on `js-product` alone would double every product.
12	const CARD_RE = /<div class="t776__col[^"]*js-product" data-product-lid="(\d+)"/g;
13	const TITLE_RE = /<div class="[^"]*t-title[^"]*"[^>]*>([\s\S]*?)<\/div>/;
14	const IMAGE_RE = /data-original="([^"]+)"/;
15	// The closing guard is the Unicode lookahead, not `\b`: in JavaScript `\b` is ASCII-only even with the `u`
16	// flag, so there is never a word boundary after a Cyrillic unit word.
17	const UNIT_RE =
18	  /\d+(?:[.,]\d+)?(?:\s*(?:кг|г|шт|мл|л))?(?:\s*-\s*\d+(?:[.,]\d+)?)?\s*(?:кг|г|шт|мл|л)(?![\p{L}\p{N}])/u;
19	
20	const NAMED_ENTITIES: Record<string, string> = {
21	  amp: "&",
22	  lt: "<",
23	  gt: ">",
24	  quot: '"',
25	  apos: "'",
26	  nbsp: " ",
27	  laquo: "«",
28	  raquo: "»",
29	  mdash: "—",
30	  ndash: "–",
31	  hellip: "…",
32	};
33	
34	function decodeEntities(value: string): string {
35	  return value.replace(/&(#x[0-9a-fA-F]+|#\d+|[a-zA-Z]+);/g, (entity, body: string) => {
36	    if (!body.startsWith("#")) return NAMED_ENTITIES[body.toLowerCase()] ?? entity;
37	    const code = body.startsWith("#x") ? Number.parseInt(body.slice(2), 16) : Number.parseInt(body.slice(1), 10);
38	    return Number.isInteger(code) && code >= 0 && code <= 0x10ffff ? String.fromCodePoint(code) : entity;
39	  });
40	}
41	
42	/** Strip tags, decode entities, collapse whitespace runs to one space. */
43	function plainText(html: string): string {
44	  return decodeEntities(html.replace(/<[^>]*>/g, " "))
45	    .replace(/\s+/g, " ")
46	    .trim();
47	}
48	
49	function fieldText(cardHtml: string, field: string, lid: string): string | undefined {
50	  const match = new RegExp(`field="${field}__${lid}"\\s*>([\\s\\S]*?)</div>`).exec(cardHtml);
51	  return match ? plainText(match[1] ?? "") : undefined;
52	}
53	
54	function readCard(cardHtml: string, lid: string, recordId: string, category: string): Product | undefined {
55	  const name = fieldText(cardHtml, "li_title", lid);
56	  const price = fieldText(cardHtml, "li_price", lid);
57	  if (!name || !price || !/^\d+$/.test(price)) return undefined;
58	  return {
59	    id: `${SHOP_KEY}:${lid}`,
60	    shopKey: SHOP_KEY,
61	    shopName: SHOPS[SHOP_KEY].name,
62	    sourceId: lid,
63	    name,
64	    price: Number(price),
65	    currency: "UAH",
66	    imageUrl: IMAGE_RE.exec(cardHtml)?.[1] ?? "",
67	    productUrl: `${PAGE_URL}#${recordId}`,
68	    description: fieldText(cardHtml, "li_descr", lid) ?? "",
69	    category,
70	    unit: UNIT_RE.exec(name)?.[0] ?? "",
71	    inStock: true,
72	  };
73	}
