75	/** Pure parser over the Tilda page — the fixture tests call it without any fetch. */
76	export function parseKarashynyardHtml(html: string): Product[] {
77	  const products: Product[] = [];
78	  const seen = new Set<string>();
79	  let category = "";
80	
81	  const records = [...html.matchAll(RECORD_RE)];
82	  records.forEach((record, index) => {
83	    const recordId = record[1] ?? "";
84	    const body = html.slice(record.index + record[0].length, records[index + 1]?.index ?? html.length);
85	    if (record[2] !== "776") {
86	      const title = TITLE_RE.exec(body);
87	      if (title) category = plainText(title[1] ?? "");
88	      return;
89	    }
90	    const cards = [...body.matchAll(CARD_RE)];
91	    cards.forEach((card, cardIndex) => {
92	      const lid = card[1] ?? "";
93	      // Tilda reuses lids across records; ids must be unique, so the first card with a lid wins.
94	      if (seen.has(lid)) return;
95	      const product = readCard(body.slice(card.index, cards[cardIndex + 1]?.index ?? body.length), lid, recordId, category);
96	      if (!product) return;
97	      seen.add(lid);
98	      products.push(product);
99	    });
100	  });
101	
102	  return products;
103	}
