      <p className="mt-2 text-base font-semibold text-stone-900">{formatPrice(product.price)}</p>
      <a
        href={product.productUrl}
        aria-label={`У магазині: ${product.name}`}
        className="mt-3 text-sm text-emerald-700 underline"
